<?= $this->extend('layouts/app') ?><?= $this->section('content') ?><?= view('partials/breadcrumbs',['title'=>$title,'subtitle'=>'Keep asset information accurate for reliable availability monitoring.']) ?><section class="panel form-panel"><form method="post" action="<?= $equipment?site_url('equipment/'.$equipment['id']):site_url('equipment') ?>" class="form-grid"><?= csrf_field() ?><label>Asset Code <span>*</span><input name="asset_code" value="<?= esc(old('asset_code',$equipment['asset_code']??'')) ?>" required></label><label>Equipment Name <span>*</span><input name="name" value="<?= esc(old('name',$equipment['name']??'')) ?>" required></label><label>Category <span>*</span><select name="category_id" required><option value="">Select category</option><?php foreach($categories as $c): ?><option value="<?= $c['id'] ?>" <?= (string)old('category_id',$equipment['category_id']??'')===(string)$c['id']?'selected':'' ?>><?= esc($c['name']) ?></option><?php endforeach; ?></select></label><label>Storage Location <span>*</span><select name="location_id" required><option value="">Select location</option><?php foreach($locations as $l): ?><option value="<?= $l['id'] ?>" <?= (string)old('location_id',$equipment['location_id']??'')===(string)$l['id']?'selected':'' ?>><?= esc($l['name']) ?></option><?php endforeach; ?></select></label><label>Total Quantity <span>*</span><input type="number" min="0" name="total_quantity" value="<?= esc(old('total_quantity',$equipment['total_quantity']??0)) ?>" required></label><label>Unit <span>*</span><input name="unit" value="<?= esc(old('unit',$equipment['unit']??'piece')) ?>" required></label><label>Condition <span>*</span><select name="condition"><?php foreach(config('BantayGamit')->conditions as $k=>$v): ?><option value="<?= esc($k) ?>" <?= old('condition',$equipment['condition']??'good')===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select></label><label>Status <span>*</span><select name="status"><?php foreach(config('BantayGamit')->equipmentStatuses as $k=>$v): ?><option value="<?= esc($k) ?>" <?= old('status',$equipment['status']??'available')===$k?'selected':'' ?>><?= esc($v) ?></option><?php endforeach; ?></select></label><label>Acquired Date<input type="date" name="acquired_date" value="<?= esc(old('acquired_date',$equipment['acquired_date']??'')) ?>"></label><label class="wide-field">Description<textarea name="description" rows="3"><?= esc(old('description',$equipment['description']??'')) ?></textarea></label><label class="wide-field">Notes<textarea name="notes" rows="3"><?= esc(old('notes',$equipment['notes']??'')) ?></textarea></label><div class="form-actions wide-field"><a class="btn" href="<?= site_url('equipment') ?>">Cancel</a><button class="btn primary" type="submit"><?= ui_icon('save') ?> Save Equipment</button></div></form></section><?= $this->endSection() ?>
